import{_ as o,l as s,o as e,c as l,v as t,p as n,x as i,d as p,i as A,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"IPv6 过渡技术","description":"","frontmatter":{"title":"IPv6 过渡技术","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ipv6-transition.md","filePath":"cs/ipv6-transition.md","lastUpdated":1789023840000}'),v={name:"cs/ipv6-transition.md"};function c(h,a,P,T,_,m){const r=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="ipv6-过渡技术" tabindex="-1">IPv6 过渡技术 <a class="header-anchor" href="#ipv6-过渡技术" aria-label="Permalink to &quot;IPv6 过渡技术&quot;">​</a></h1><div class="epigraph"><p>双栈、隧道、翻译三条路：主机同时两套、用 IPv4 云运 IPv6（或反过来）、或 NAT64 改头；没有免费的「只打开 v6」。</p><footer>—— 据 RFC 4213 双栈与隧道；RFC 6146 NAT64；RFC 6180 过渡指导整理</footer></div><p>主干<a href="/cs/ipv6-contrast">IPv6 对照</a> 与 <a href="/cs/ipv6-ndp">NDP</a> 已给地址与邻居。<a href="/cs/multicast-igmp-pim">上一课</a> 的 MLD 是 v6 侧 IGMP。缺口是<strong>与仍在的 IPv4 共存</strong>：6in4、DS-Lite、464XLAT、NAT64/DNS64。本课不把 PMTUD 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>核心若只会 v4，边缘已有 v6 主机：要隧道（GRE/6in4/IP-in-IP）或翻译。翻译破坏端到端地址真值，应用 ALGs 脆弱——<a href="/cs/layering-e2e">端到端论证</a> 在此再次出场。双栈：每应用选栈，DNS 有 A/AAAA，Happy Eyeballs 竞速。CGN 把 v4 节省下来，不推进 v6，只拖延。</p><p>不要把 IPv6 过渡写成安全课：IPsec 曾被神话为 v6 内置强制，实践不是。</p><p><span class="marginnote">RFC 6180 分类场景。464XLAT 让 IPv4 套接字在 v6-only 网上活。本课不把每个实验 RFC 列成清单。</span></p><h3 id="没有免费只开-v6" tabindex="-1">没有免费只开 v6 <a class="header-anchor" href="#没有免费只开-v6" aria-label="Permalink to &quot;没有免费只开 v6&quot;">​</a></h3><p>双栈最干净；隧道穿越；翻译牺牲地址真值。v6 无源分片，更依赖 PMTUD。CGN 只拖延 v4。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照三列：双栈 / 隧道 / 翻译。画：AAAA → 原生 v6；否则 DNS64 合成 → NAT64。与 VXLAN 对照：都是封装，过渡隧道的「租户」是地址族。</p>',11)),(e(),n(d,null,{default:i(()=>[A(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DS%5B%22%E5%8F%8C%E6%A0%88%22%5D%20--%3E%20APP%5B%22%E5%BA%94%E7%94%A8%E9%80%89%20A%2FAAAA%22%5D%0A%20%20TUN%5B%22%E9%9A%A7%E9%81%93%22%5D%20--%3E%20CORE4%5B%22v4%20%E6%A0%B8%E5%BF%83%E8%BF%90%20v6%22%5D%0A%20%20XL%5B%22NAT64%22%5D%20--%3E%20TR%5B%22%E6%94%B9%E5%86%99%E5%9C%B0%E5%9D%80%E4%B8%8E%E7%AB%AF%E5%8F%A3%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>BGP 可同时带 v4/v6 地址族；RPKI 也有 v6 ROA。MTU：隧道再扣头，v6 不允许源分片，更依赖 PMTUD 下一课。ECMP 要按新五元组。手机核心常 v6-only + 464XLAT，接住蜂窝课的锚点。</p><p>SIIT 无状态翻译与 NAT64 有状态：规模与日志不同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 MAP-T 的端口映射数学全文。路径 MTU 发现是下一课。后课默认：过渡是封装或翻译，双栈是最干净但最贵的并存。</p><p>只部署 SLAAC 而不管 DNS 与防火墙，过渡等于没做。</p><p>上一课留下的缺口在本课收口；「IPv6 过渡技术」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/pmtud">路径 MTU 发现</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>双栈并存、隧道穿越、翻译妥协。</li><li>翻译牺牲地址真值与部分应用。</li><li>v6-only 边缘常用 NAT64/XLAT。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 4213；RFC 6146；RFC 6180。</li></ul>',10))])}const f=o(v,[["render",c]]);export{u as __pageData,f as default};
